INSERT INTO "services" ("id","slug","name","short_description","hero_headline","hero_subheadline","hero_image_url","icon","problem_description","recovery_process","success_rate","stats","seo_title","seo_description","og_image_url","is_published","sort_order","created_at","updated_at") VALUES('2','forex-recovery','Forex Recovery','Recover lost forex investments.','Specialized Forex Fund Recovery',NULL,NULL,NULL,NULL,NULL,NULL,'{}',NULL,NULL,NULL,1,2,'2026-04-26T11:05:50.601Z','2026-04-26T11:05:50.601Z');
INSERT INTO "services" ("id","slug","name","short_description","hero_headline","hero_subheadline","hero_image_url","icon","problem_description","recovery_process","success_rate","stats","seo_title","seo_description","og_image_url","is_published","sort_order","created_at","updated_at") VALUES('2c7b31ce-5fe9-4a3f-b747-3c33fa3b51bc','crypto-deep-trace','Cryptocurrency Deep-Trace','Military-grade blockchain forensics to pierce through mixers, peeling chains, and obfuscated transactions.','Total Blockchain Dominance','If it touched a ledger, we can find it. We trace the untraceable to reclaim your digital sovereignty.',NULL,'Bitcoin','Modern scammers use sophisticated obfuscation like Wasabi mixers, CoinJoin, and cross-chain hops to vanish. Standard investigators stop at the first hop.','We utilize private node-level data and proprietary heuristics to unmask wallet clusters. Our team identifies the off-ramp exit point and coordinates with global law enforcement to freeze the bounty.','98%','{}',NULL,NULL,NULL,1,1,'2026-04-27T01:36:09.340Z','2026-04-27T01:36:09.340Z');
INSERT INTO "services" ("id","slug","name","short_description","hero_headline","hero_subheadline","hero_image_url","icon","problem_description","recovery_process","success_rate","stats","seo_title","seo_description","og_image_url","is_published","sort_order","created_at","updated_at") VALUES('a74b8fd1-8079-4c8d-8f38-749625ab70c5','syndicate-infiltration','Syndicate Infiltration','Specialized unit for de-anonymizing organized Pig Butchering and Romance scam networks operating out of SE Asia.','Dismantle the Network','We dont just find your money; we identify the architects. Precision intelligence for international asset seizure.',NULL,'ShieldAlert','Victims are targeted by vast, organized syndicates using psychological warfare. They hide behind shell companies and complex mule networks.','Our deep-web intelligence team infiltrates the communication channels and technical infrastructure of the syndicate. We map the flow to high-level beneficiaries, providing the proof required for jurisdictional arbitration.','91%','{}',NULL,NULL,NULL,1,2,'2026-04-27T01:36:09.378Z','2026-04-27T01:36:09.378Z');
INSERT INTO "services" ("id","slug","name","short_description","hero_headline","hero_subheadline","hero_image_url","icon","problem_description","recovery_process","success_rate","stats","seo_title","seo_description","og_image_url","is_published","sort_order","created_at","updated_at") VALUES('04ff79b9-2089-4ba5-abf9-14d481e124fa','forex-arbitration','Forex & Broker Arbitration','Forcing unregulated platforms and rogue brokers into capital restitution through international banking pressure.','Capital Sovereignty Restored','Rogue brokers rely on your silence. We speak the language of international financial law to force their hand.',NULL,'DollarSign','Unregulated brokers simulate trades to manufacturing "losses". They block withdrawals and demand more capital, holding your assets hostage.','We leverage the financial ombudsman protocols and chargeback representment. By proving the platform used manipulative software, we force the facilitating banks to reverse the principal transfers.','94%','{}',NULL,NULL,NULL,1,3,'2026-04-27T01:36:09.430Z','2026-04-27T01:36:09.430Z');
INSERT INTO "services" ("id","slug","name","short_description","hero_headline","hero_subheadline","hero_image_url","icon","problem_description","recovery_process","success_rate","stats","seo_title","seo_description","og_image_url","is_published","sort_order","created_at","updated_at") VALUES('71358325-2f4f-42ed-b55e-ad610963fcce','executive-wealth','Executive Wealth Recovery','Bespoke recovery strategies for HNWIs and corporations facing complex multi-jurisdictional financial fraud.','Elite Asset Reclamation','Discretion, precision, and absolute dominance in international recovery. Reserved for high-stakes capital loss.',NULL,'Landmark','High-net-worth individuals are targets for "bespoke" investment scams involving fake hedge funds and private equity fraud.','Our legal and forensic teams coordinate across borders to issue Anton Piller orders and Mareva injunctions. We secure the assets globally before the perpetrators can liquidate.','99%','{}',NULL,NULL,NULL,1,4,'2026-04-27T01:36:09.445Z','2026-04-27T01:36:09.445Z');
INSERT INTO "services" ("id","slug","name","short_description","hero_headline","hero_subheadline","hero_image_url","icon","problem_description","recovery_process","success_rate","stats","seo_title","seo_description","og_image_url","is_published","sort_order","created_at","updated_at") VALUES('3d9f54c2-ff05-4913-a293-cc759e3793dc','romance-fraud-remediation','Romance Fraud Remediation','Emotional and financial restoration. We identify the perpetrators behind digital manipulation schemes.','Truth from Deception','They exploited your trust; we exploit their digital footprint. Reclaim your pride and your assets.',NULL,'HeartCrack','Romance scams are a brutal form of social engineering. Funds are often moved through gift cards, mules, or crypto to evade detection.','We conduct full digital footprint analysis to find the "human error" in the scammer''s setup. Once identified, we use legal pressure on the receiving institutions to claw back the value.','87%','{}',NULL,NULL,NULL,1,5,'2026-04-27T01:36:09.466Z','2026-04-27T01:36:09.466Z');
